fn handle<'a>(&'a self, invocation: ToolInvocation) -> codex_tools::ToolExecutorFuture<'a>
    where
        ToolInvocation: 'a,
    {
        Box::pin(async move {
            let ToolInvocation {
                payload,
                step_context,
                ..
            } = invocation;
            let arguments = match payload {
                ToolPayload::Function { arguments } => arguments,
                _ => {
                    return Err(FunctionCallError::Fatal(format!(
                        "{WAIT_FOR_ENVIRONMENT_TOOL_NAME} handler received unsupported payload"
                    )));
                }
            };
            let args: WaitForEnvironmentArgs = parse_arguments(&arguments)?;
            let environment_id = args.environment_id;
            let already_ready = step_context
                .environments
                .turn_environments()
                .any(|environment| environment.selection.environment_id == environment_id);
            if !already_ready {
                if let Some(error) =
                    step_context
                        .environments
                        .environments
                        .iter()
                        .find_map(|state| match state {
                            TurnEnvironmentState::Failed {
                                selection, error, ..
                            } if selection.environment_id == environment_id => Some(error),
                            _ => None,
                        })
                {
                    return Err(environment_failure(&environment_id, error));
                }
                let Some(environment) = step_context
                    .environments
                    .starting()
                    .find(|environment| environment.selection.environment_id == environment_id)
                    .cloned()
                else {
                    return Err(FunctionCallError::RespondToModel(format!(
                        "environment `{environment_id}` is neither ready nor starting"
                    )));
                };

                environment
                    .wait_until_ready()
                    .await
                    .map_err(|error| environment_failure(&environment_id, &error.to_string()))?;
            }

            Ok(boxed_tool_output(JsonToolOutput::new(json!({
                "environment_id": environment_id,
                "status": "ready",
            }))))
        })
    }

